#!/usr/bin/env python3
"""Build a compact standalone catalog from local candidate/factor CSVs."""
import csv,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent.parent
QUEUE=ROOT/'data/normalized/costar/human-review-queue.csv'
CARDS=ROOT/'data/normalized/costar/factor-cards.csv'
CANDIDATES=ROOT/'data/normalized/costar/restaurant-site-candidates.csv'
CONTEXT=ROOT/'data/normalized/costar/local-context.csv'
SCORES=ROOT/'data/normalized/costar/diligence-scorecard.csv'
OUT=ROOT/'data/normalized/costar/catalog.html'
def read(p):
    with p.open(newline='',encoding='utf-8') as f:return list(csv.DictReader(f))
def main():
    sites=read(QUEUE);coords={r['property_id']:r for r in read(CANDIDATES)};context={r['property_id']:r for r in read(CONTEXT)};scores={r['property_id']:r for r in read(SCORES)};by_site={}
    for c in read(CARDS):by_site.setdefault(c['property_id'],[]).append(c)
    data=json.dumps([{'id':s['property_id'],'city':s['city'],'address':s['address'],'status':s['listing_statuses'],'area':s['active_listed_min_available_sqft'],'lat':coords.get(s['property_id'],{}).get('latitude',''),'lon':coords.get(s['property_id'],{}).get('longitude',''),'retail':context.get(s['property_id'],{}).get('nearby_general_retail_count',''),'incidents':context.get(s['property_id'],{}).get('reported_incidents_0_5mi',''),'foodPeers':context.get(s['property_id'],{}).get('nearby_food_service_historic_tenant_property_count',''),'readiness':scores.get(s['property_id'],{}).get('evidence_readiness_score_0_100',''),'diligence':scores.get(s['property_id'],{}).get('diligence_risk_score_0_100',''),'crimePeriod':context.get(s['property_id'],{}).get('crime_source_date_start','')+' to '+context.get(s['property_id'],{}).get('crime_source_date_end',''),'factors':by_site.get(s['property_id'],[])} for s in sites],ensure_ascii=False).replace('</','<\\/')
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(HTML.replace('__DATA__',data),encoding='utf-8')
    print(f'Wrote {OUT.relative_to(ROOT)} for {len(sites)} candidates.')
HTML='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Candidate locations</title><style>
:root{font:14px/1.45 Inter,ui-sans-serif,system-ui,sans-serif;color:#17251f;background:#f2f4f1}*{box-sizing:border-box}body{margin:0}header{padding:24px max(20px,calc((100vw - 1200px)/2));background:#173f32;color:white}header h1{font-size:25px;margin:0}header p{margin:4px 0 0;color:#d4e0d9}main{max-width:1200px;margin:18px auto;padding:0 18px}.warning{padding:10px 13px;background:#fff3d2;border:1px solid #ead6a1;border-radius:8px;margin-bottom:13px;font-size:13px}.tools{display:flex;gap:8px;margin:12px 0}.tools input,.tools select{font:inherit;padding:9px 11px;border:1px solid #d7ded9;border-radius:7px;background:white}.tools input{flex:1}.count{font-size:12px;color:#65746c;margin:8px 2px}.row{display:grid;grid-template-columns:190px minmax(160px,1.15fr) minmax(410px,2.2fr);gap:16px;align-items:center;background:#fff;border:1px solid #dfe5e0;border-radius:9px;margin:8px 0;padding:10px}.photo{width:190px;height:112px;object-fit:cover;border-radius:6px;background:#e8ece8;color:#65746c;font-size:12px}.title{font-weight:700;font-size:16px}.sub{font-size:12px;color:#627067}.status{display:inline-block;margin-top:6px;padding:3px 7px;border-radius:20px;background:#eef2ef;font-size:11px;color:#46564d}.metrics{display:grid;grid-template-columns:repeat(4,minmax(82px,1fr));gap:7px}.metric{border-left:1px solid #e6eae6;padding:3px 8px}.metric b{display:block;font-size:12px}.metric span{font-size:12px;color:#66736c}.unknown{color:#80651e!important}.detail{grid-column:1/-1;border-top:1px solid #e8ece8;padding:8px 3px 2px}.detail summary{cursor:pointer;font-weight:650;font-size:13px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 18px}.factor{padding:9px 0;border-bottom:1px solid #eff1ef}.factor b{display:block}.meta{font-size:11px;color:#69756e}.foot{color:#67736c;font-size:12px;margin:18px 2px}@media(max-width:850px){.row{grid-template-columns:130px 1fr}.photo{width:130px;height:92px}.metrics{grid-column:1/-1;grid-template-columns:repeat(4,1fr)}.detail{grid-column:1/-1}}@media(max-width:520px){main{padding:0 9px}.row{grid-template-columns:95px 1fr;gap:10px}.photo{width:95px;height:80px}.metrics{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:1fr}.tools{flex-wrap:wrap}.tools input{min-width:100%}}
</style></head><body><header><h1>Candidate locations</h1><p>Houston · Los Angeles · evidence-first catalog</p></header><main><div class="warning"><b>Exploratory factor indicators, not a validated site ranking.</b> Evidence readiness and diligence are checklist measures. Nearby food-service properties are historical CoStar context, not a validated competition score. Incident counts are not safety scores.</div><div class="tools"><input id="search" placeholder="Search site or address" aria-label="Search"><select id="city"><option value="">All cities</option><option>Houston</option><option>Los Angeles</option></select></div><div id="count" class="count"></div><section id="list"></section><p class="foot">External OpenStreetMap embeds are location previews, not property photographs. Evidence readiness and diligence are exploratory checklist scores, not fit or success measures. ¹Historical food-service CoStar property count within 1 mile; not validated competitor count. ²Houston partial-year reported incidents within 0.5 mile; not a safety score; LA unavailable. Individual factor details show provenance and limitations where present.</p></main><script>
const sites=__DATA__;const list=document.querySelector('#list');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){let q=document.querySelector('#search').value.toLowerCase(),city=document.querySelector('#city').value;let rows=sites.filter(s=>(!city||s.city===city)&&(`${s.id} ${s.city} ${s.address}`.toLowerCase().includes(q))).sort((a,b)=>a.city.localeCompare(b.city)||a.address.localeCompare(b.address));document.querySelector('#count').textContent=`${rows.length} candidates · alphabetical, not ranked`;list.innerHTML=rows.map(s=>{let get=id=>s.factors.find(f=>f.factor_id===id),area=get('property_market'),competition=get('mobility_tourism'),crime=get('crime_safety'),access=get('traffic_access');let metrics=[['Evidence readiness',s.readiness?`${s.readiness}/100`:'Not calculated'],['Diligence checklist',s.diligence?`${s.diligence}/100`:'Not calculated'],['Food-service peers¹',s.foodPeers?`${s.foodPeers} properties`:'0 reported'],['Incident context²',s.incidents?`${s.incidents} incidents`:'Unavailable']];let details=s.factors.map(f=>`<div class="factor"><b>${esc(f.factor_name)} <span class="meta">· ${esc(f.status)}</span></b>${f.value?`<div>${esc(f.value)} ${esc(f.unit)}</div>`:`<div class="meta unknown">Unknown: ${esc(f.unknown_reason||'No verified evidence')}</div>`}<div class="meta">${[f.source&&`Source ${f.source}`,f.record_id&&`Record ${f.record_id}`,f.retrieved_or_observed_date&&`Date ${f.retrieved_or_observed_date}`,f.geography&&`Geography ${f.geography}`,f.time_window&&`Period ${f.time_window}`].filter(Boolean).map(esc).join(' · ')}</div>${f.uncertainty?`<div class="meta">${esc(f.uncertainty)}</div>`:''}</div>`).join('');let map=s.lat&&s.lon?`https://www.openstreetmap.org/export/embed.html?bbox=${Number(s.lon)-0.006}%2C${Number(s.lat)-0.004}%2C${Number(s.lon)+0.006}%2C${Number(s.lat)+0.004}&layer=mapnik&marker=${s.lat}%2C${s.lon}`:'';return `<article class="row"><iframe class="photo" loading="lazy" title="Map preview near ${esc(s.address)}" src="${map}" referrerpolicy="no-referrer" onerror="this.style.display='none'"></iframe><div><div class="title">${esc(s.address)}</div><div class="sub">${esc(s.city)} · Property ${esc(s.id)}</div><span class="status">Source status: ${esc(s.status||'unknown')} · snapshot</span><div class="sub">Listed area: ${s.area?`${esc(s.area)} sq ft`:'unknown'}</div></div><div class="metrics">${metrics.map(m=>`<div class="metric"><b>${m[0]}</b><span class="unknown">${m[1]}</span></div>`).join('')}</div><details class="detail"><summary>View 15 individual factor cards</summary><div class="cards">${details}</div></details></article>`}).join('')||'<p>No matching sites.</p>'}document.querySelector('#search').addEventListener('input',render);document.querySelector('#city').addEventListener('change',render);render();</script></body></html>'''
if __name__=='__main__':main()
